export type SettingsChange = Partial<Omit<Settings, 'dated'>> & { from?: Record<string, string> };

/** A user's role on a sheet. A name with no role assigned is a clerk. */
export type Role = { user: string; role: string };

export const ROLES = ['clerk', 'steward'] as const;

export const settingsKey = (sheetId: string) => ['sheet', sheetId, 'settings'] as const;
export const rolesKey = (sheetId: string) => ['sheet', sheetId, 'roles'] as const;

export function useSettings(sheetId: string) {
    setError('');
    const name = fields.user.trim();
    const role = fields.role.trim();
    if (name === '') {
      setError('A user name is required.');
      return;
    }
    if (!(ROLES as readonly string[]).includes(role)) {
      setError('A role is clerk or steward.');
      return;
    }
    once((done) => save.mutate({ user: name, role }, { onSettled: done }));
  };

  const change = (next: Partial<Role>) => {
    setFields((f) => ({ ...f, ...next }));
    if (permsTouched.size > 0) {
      const perms: Record<string, string> = {};
      for (const action of ACTIONS) {
        if (!permsTouched.has(action)) continue;
        const roles = (permFields[action] ?? '').trim();
        if (roles !== '' && !roles.split(',').every((r) => (ROLES as readonly string[]).includes(r.trim()))) {
          setError(`Who may ${action} is clerk or steward, separated by commas, or blank.`);
          return;
        }
        perms[action] = roles;
      }
